/// <summary>
/// The <c>MetTransferOrderAutoShipContract</c> is responsible for carrying parameters for the automatic shipment of transfer orders.
/// </summary>
[
    DataContractAttribute,
    SysOperationContractProcessingAttribute(classStr(MetTransferOrderAutoShipUIBuilder))
]
public class MetTransferOrderAutoShipContract implements SysOperationInitializable, SysOperationValidatable
{
    WHSReleaseQuantitySpecification     releaseQuantitySpecification;
    NoYes                               allowPartiallyReleased;
    NoYes                               groupIntoMultipleReleases;
    Query                               query;
    str                                 packedQuery;


}

Method.Source:
/// <summary>
/// Initializes the contract.
/// </summary>
public void initialize()
{
    query = new Query(queryStr(MetTransferOrderAutoShipQuery));
    this.parmQuery(query);
}

/// <summary>
/// Gets or sets the value of the packed query data contract parameter.
/// </summary>
/// <param name="_packedQuery">
/// The new value of the packed query data contract parameter; optional.
/// </param>
/// <returns>
/// The current value of the packed query data contract parameter.
/// </returns>
[
    DataMemberAttribute,
    AifQueryTypeAttribute('_packedQuery', queryStr(MetTransferOrderAutoShipQuery))
]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;
    return packedQuery;
}

/// <summary>
/// Gets or sets the query that provides the sorted list of transfer orders that should be auto shipped.
/// </summary>
/// <param name="_query">
/// The query that provides the sorted list of transfer orders that should be auto shipped.
/// </param>
/// <returns>
/// The query that provides the sorted list of transfer orders that should be auto shipped.
/// </returns>
public Query parmQuery(Query _query = query)
{
    if (prmisDefault(_query))
    {
        // Cannot return query directly as this query may not contain any datasource information, so query need to be initialized from packed query str
        query = new Query(SysOperationHelper::base64Decode(packedQuery));
    }
    else
    {
        packedQuery = SysOperationHelper::base64Encode(_query.pack());
        query = _query;
    }
    return query;
}

public boolean validate()
{
    if (!this.parmQuery().dataSourceTable(tableNum(InventTransferTable)))
    {
        return checkFailed(strFmt("@SYS303331", tableStr(InventTransferTable)));
    }
    return true;
}
